                <FieldContent className="min-w-0 flex-initial">
                  <FieldTitle className="min-w-0 text-base break-words">{option.label}</FieldTitle>
                  {option.description != null && (
                    <FieldDescription>{option.description}</FieldDescription>
                  )}
