                <RadioGroupItem
                  id={id}
                  value={option.value}
                  className={cn('sr-only', option.radioClassName)}
                  disabled={groupProps.disabled || option.disabled}
                  aria-invalid={controlProps['aria-invalid']}
                />
              </Field>
            </FieldLabel>
          );
        })}
      </RadioGroup>
    </FormField>
  );
}

import type { Icon } from '@tabler/icons-react';

import type { RadioCardOption } from './radio-card-field';

export type SeverityLevel = 'Low' | 'Medium' | 'High' | 'Critical';

type SeverityStyle = { icon: string; card: string; radio: string };

export const SEVERITY_CARD_STYLES = {
  Low: {
    icon: 'text-green-600',
    card: 'border-green-600/30 text-green-600 not-has-data-checked:hover:bg-green-600/5! has-data-checked:border-green-600 has-data-checked:bg-green-600/10! dark:has-data-checked:bg-green-600/15!',
    radio: 'data-checked:border-green-600 data-checked:bg-green-600 dark:data-checked:bg-green-600',
  },
  Medium: {
    icon: 'text-yellow-600',
    card: 'border-yellow-600/30 text-yellow-600 not-has-data-checked:hover:bg-yellow-600/5! has-data-checked:border-yellow-600 has-data-checked:bg-yellow-600/10! dark:has-data-checked:bg-yellow-600/15!',
    radio:
      'data-checked:border-yellow-600 data-checked:bg-yellow-600 dark:data-checked:bg-yellow-600',
  },
  High: {
    icon: 'text-orange-600',
    card: 'border-orange-600/30 text-orange-600 not-has-data-checked:hover:bg-orange-600/5! has-data-checked:border-orange-600 has-data-checked:bg-orange-600/10! dark:has-data-checked:bg-orange-600/15!',
    radio:
      'data-checked:border-orange-600 data-checked:bg-orange-600 dark:data-checked:bg-orange-600',
  },
  Critical: {
    icon: 'text-red-600',
    card: 'border-red-600/30 text-red-600 not-has-data-checked:hover:bg-red-600/5! has-data-checked:border-red-600 has-data-checked:bg-red-600/10! dark:has-data-checked:bg-red-600/15!',
    radio: 'data-checked:border-red-600 data-checked:bg-red-600 dark:data-checked:bg-red-600',
  },
} satisfies Record<SeverityLevel, SeverityStyle>;

export function severityCardOption(
  value: SeverityLevel,
  label: string,
  icon: Icon,
): RadioCardOption {
  const style = SEVERITY_CARD_STYLES[value];
  return {
    value,
    label,
    icon,
    className: style.card,
    iconClassName: style.icon,
    radioClassName: style.radio,
  };
}

'use client';

import type { ReactNode } from 'react';

import { useFieldContext } from '@athenex/web-core/form';

import { cn } from '@/lib/utils';

import { FormField, useFieldControl, type FormFieldProps } from './form-field';

export type SegmentedOption = { value: string; label: ReactNode; disabled?: boolean };

export type SegmentedFieldProps = FormFieldProps & {
  options: readonly SegmentedOption[];
  disabled?: boolean;
  className?: string;
};

/**
 * The mock's segmented control (เพศ: ชาย | หญิง): equal segments in one bordered row, the chosen
 * one filled chrome green. Radios underneath for keyboard and screen readers.
 */
export function SegmentedField(props: SegmentedFieldProps) {
  const field = useFieldContext<string>();
  const { fieldProps, controlProps, inputProps } = useFieldControl(props);
  const { options, disabled, className } = inputProps;
  const value = field.state.value ?? '';

  return (
    <FormField {...fieldProps}>
      <div
        role="radiogroup"
        id={controlProps.id}
        aria-labelledby={fieldProps.label != null ? `${controlProps.id}-label` : undefined}
        aria-invalid={controlProps['aria-invalid']}
        aria-describedby={controlProps['aria-describedby']}
        className={cn(
          'flex overflow-hidden rounded-md border border-input bg-card',
          controlProps['aria-invalid'] && 'border-critical',
          className,
        )}
      >
        {options.map((option, index) => {
          const checked = option.value === value;
          const id = `${controlProps.id}-${index}`;
          return (
            <label
              key={option.value}
              htmlFor={id}
              className={cn(
                'flex h-[42px] flex-1 cursor-pointer items-center justify-center border-r border-input text-base transition-colors last:border-r-0 has-focus-visible:ring-2 has-focus-visible:ring-ring has-focus-visible:ring-inset',
                checked && 'bg-sidebar font-bold text-sidebar-foreground',
                (disabled || option.disabled) && 'cursor-not-allowed opacity-50',
              )}
            >
              <input
                id={id}
                type="radio"
                name={controlProps.name}
                value={option.value}
                checked={checked}
                disabled={disabled || option.disabled}
                onChange={() => field.handleChange(option.value)}
                onBlur={field.handleBlur}
                className="sr-only"
              />
              {option.label}
            </label>
          );
        })}
      </div>
    </FormField>
  );
}

'use client';

import type { ComponentProps } from 'react';

import { useFieldContext } from '@athenex/web-core/form';

import { NativeSelect, NativeSelectOption } from '@/components/ui/native-select';

import { FormField, useFieldControl, type FormFieldProps } from './form-field';

export type NativeSelectOptionItem = { value: string; label: string; disabled?: boolean };

export type NativeSelectFieldProps = FormFieldProps &
  Omit<
    ComponentProps<typeof NativeSelect>,
    'id' | 'name' | 'value' | 'defaultValue' | 'onChange' | 'onBlur' | 'children'
  > & {
    options: readonly NativeSelectOptionItem[];
    /** Text of the empty option; omit to force a choice from `options`. */
    placeholder?: string;
  };

/** Native `<select>` with the shared label/description/error frame (best on phones). */
export function NativeSelectField(props: NativeSelectFieldProps) {
  const field = useFieldContext<string>();
  const { fieldProps, controlProps, inputProps } = useFieldControl(props);
  const { options, placeholder, className, ...selectProps } = inputProps;

  return (
    <FormField {...fieldProps}>
      <NativeSelect
        {...selectProps}
        {...controlProps}
        className={className ?? 'w-full'}
        value={field.state.value ?? ''}
        onChange={(event) => field.handleChange(event.target.value)}
        onBlur={field.handleBlur}
      >
        {placeholder !== undefined && (
          <NativeSelectOption value="">{placeholder}</NativeSelectOption>
        )}
        {options.map((option) => (
          <NativeSelectOption key={option.value} value={option.value} disabled={option.disabled}>
            {option.label}
          </NativeSelectOption>
        ))}
      </NativeSelect>
    </FormField>
  );
}

'use client';

import type { ComponentProps, ReactNode } from 'react';

import { useFieldContext } from '@athenex/web-core/form';
import { CheckboxGroup } from '@base-ui/react/checkbox-group';

import { Checkbox } from '@/components/ui/checkbox';
import { FieldDescription, FieldLabel } from '@/components/ui/field';
import { cn } from '@/lib/utils';

import {
  CHECKBOX_GROUP_LAYOUTS,
  type CheckboxGroupLayout,
  groupOptions,
} from './checkbox-group-options';
import { FormField, useFieldControl, type FormFieldProps } from './form-field';

export type CheckboxGroupOption = {
  value: string;
  label: ReactNode;
  description?: ReactNode;
  group?: string;
  disabled?: boolean;
};

export type CheckboxGroupFieldProps = FormFieldProps &
  Omit<
    ComponentProps<typeof CheckboxGroup>,
    'id' | 'value' | 'defaultValue' | 'onValueChange' | 'onBlur' | 'children'
  > & { options: readonly CheckboxGroupOption[]; layout?: CheckboxGroupLayout };

export function CheckboxGroupField(props: CheckboxGroupFieldProps) {
  const field = useFieldContext<string[]>();
  const { fieldProps, controlProps, inputProps } = useFieldControl(props);
  const { options, layout = 'list', required, className, ...groupProps } = inputProps;
  const classes = CHECKBOX_GROUP_LAYOUTS[layout];
  const { name, ...groupControlProps } = controlProps;

  return (
    <FormField {...fieldProps}>
      <CheckboxGroup
        {...groupProps}
        {...groupControlProps}
        data-slot="checkbox-group"
        aria-labelledby={fieldProps.label != null ? `${controlProps.id}-label` : undefined}
        aria-required={required}
        className={cn(classes.groups, className)}
        value={field.state.value ?? []}
        onValueChange={(value) => field.handleChange(value)}
        onBlur={(event) => {
          if (!event.currentTarget.contains(event.relatedTarget)) field.handleBlur();
        }}
      >
        {groupOptions(options).map((group) => (
          <div key={group.name ?? ''} className={classes.group}>
            {group.name != null && (
              <p className="text-sm font-medium text-muted-foreground">{group.name}</p>
            )}
            {group.options.map((option) => {
              const optionId = `${controlProps.id}-${option.value}`;

              return (
                <div key={option.value} className="flex items-start gap-2">
                  <Checkbox
                    id={optionId}
                    name={name}
                    value={option.value}
                    className="mt-0.5"
                    disabled={groupProps.disabled || option.disabled}
                    aria-invalid={controlProps['aria-invalid']}
                  />
                  <div className="flex flex-col gap-0.5">
                    <FieldLabel htmlFor={optionId}>{option.label}</FieldLabel>
                    {option.description != null && (
                      <FieldDescription className="text-xs">{option.description}</FieldDescription>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        ))}
      </CheckboxGroup>
    </FormField>
  );
}

export type OptionGroup<TOption> = {
  name: string | undefined;
  options: TOption[];
};

export function groupOptions<TOption extends { group?: string }>(
  options: readonly TOption[],
): OptionGroup<TOption>[] {
  const groups = new Map<string | undefined, TOption[]>();

  for (const option of options) {
    const group = groups.get(option.group);
    if (group) group.push(option);
    else groups.set(option.group, [option]);
  }

  return Array.from(groups, ([name, groupedOptions]) => ({ name, options: groupedOptions }));
}

export type CheckboxGroupLayout = 'list' | 'grid';

export const CHECKBOX_GROUP_LAYOUTS = {
  list: {
    groups: 'flex w-full flex-col gap-5',
    group: 'flex flex-col gap-3',
  },
  grid: {
